-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (624, '5.2', $t$ASK 624.5: a judgment whose own deciding lines disagree after the gate is sent the disagreement before it is counted; a KEEP is uncured$t$,
  $t$After the cure, the send-back and the gate have changed a judge's lines, the engine checks that the judgment still agrees with itself, and sends the judge each disagreement before the seat is counted. The judge chooses which line changes (ruling 428). No instruction to a judge changes: the item text names the two lines that disagree, as every send-back item does. Expected effect: no seat is counted for one side while its own WHICH HOLDS names the other (42373: chatgpt counted HELD, DEFENDER WINS, beside "WHICH HOLDS: CHALLENGER"). (plan rev 2, OBJECTIVE, plan624_5.md)$t$,
  'in part',
  $t$Written by W4 at 20:37 CST 2026-11-24 on the operator's press "Write it", and read back MATCH by W1 (Wall 11893, 11895; audit 41900). Engine 912dd47a to 2df7f6fa, the Shared Library only, 423 nodes; the child aad0ad9c is unchanged and takes the engine's library in the call. What it does: a new Library entry SCK624 reads each judge's text after the gate with the engine's recomputed verdict word and raises three kinds of item (WHICH HOLDS against the verdict; a retracted pair a line still rests on; one pair with two grades); the late gate sends them, also when they are the only late items; a CHANGE TO a WHICH HOLDS line is now a form the engine reads, at the gate, the late gate and the Alternate Merge apply (Send Back Build unchanged; Wall 11898); an item is cured only when a change is applied and the second check no longer finds it; a KEEP or no answer is uncured and adds to drv_uncured (the operator's choice, 19:08 CST). IN PART, because nothing of it is shown by a run: no run has been made since the write (debate_results last row 17:21 CST 2026-11-24, run 42373). Shown offline: t624 ALL PASS on W4's and W1's copies; of the twelve stored judgments of runs 41736, 41822, 42071 and 42373 only judgment 1276 (chatgpt, 42373) raises items, three sent and two recorded only, each a real disagreement in the judge's own text (W1, Wall 11878). The grading: the plan rev 1 PASS WITH N1 to N4 (Wall 11841), applied in rev 2; build rev 0 FAIL on one fix, F1, three catch blocks that recorded nothing (ASK 599 rule 7; Wall 11878); build rev 1 PASS (Wall 11883). Stated deviations of the build from the plan (notes624_5.md; W1's notes, Wall 11878): the form gate SB_FORM was changed beside sbLabel0, so the WHICH HOLDS change is applied at the first gate too; a retraction item on a ruling or APPLIED line is recorded and not sent; a seat with only self-check items gets one more judge call. Stated cost (plan WRONG-IF 1): a judge that does not answer the item in form loses the count for it. Open: two live runs (the operator's rule of 10:38 CST 2026-11-24); the item is likely rare, so the first runs may not exercise it.$t$,
  '11841, 11878, 11881, 11883, 11893, 11895, 11898',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$18:00 CST 2026-11-24, on the ASK 624 card: "Wait for a run; plan part 5 now" (as quoted in plan624_5.md: "Reasoning is untouched. W4 plans the engine check for a judgment that contradicts itself."). 19:08 CST, on W4's build card (cmsg_017ZQamDMHrS6fqMHnQDVo58PHjaa5R3VRMARR8G6PNgP4): "Build; a KEEP is uncured". 20:37 CST, on W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo585kmeXw4kUsHDTh7ctKAfHj, "Write ASK 624.5 (send a judgment's self-contradictions back) to live now?", options "Write it" / "Hold"): "Write it". The two cards are from W4's thread notes to W3; W3 did not read them.$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 624.5 (send a judgment's self-contradictions back) to live now?", "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo585kmeXw4kUsHDTh7ctKAfHj", "options": "Write it / Hold", "press_time": "20:37 CST 2026-11-24", "build_card": {"card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58PHjaa5R3VRMARR8G6PNgP4", "answer": "Build; a KEEP is uncured", "press_time": "19:08 CST 2026-11-24"}, "source": "W4's thread notes to W3, 20:38 and 20:39 CST 2026-11-24; Wall 11893. Not read by W3."}$j$::jsonb,
  'W4',
  $j${"md5": "e45867d2", "path": "ask624/w4/plan624_5.md", "note": "rev 2 (sha256 prefix 47c54193, the name W4 uses); rev 1 graded PASS WITH N1 to N4 by W1 (Wall 11841, sha256 b4164b24), N1 to N4 applied in rev 2", "source": "md5sum, sha256sum and read by W3; Wall 11841"}$j$::jsonb,
  $j$[{"md5": "7f129112", "path": "ask624/w4/b1/tg/target_engine_624.json", "note": "the engine target as written (sha256 prefix bafa0a0c, the name W4 and W1 use)", "source": "md5sum and sha256sum by W3; Wall 11893, 11895"}, {"md5": "3a8618b9", "path": "ask624/w4/b1/b624.cjs", "note": "the build, rev 1", "source": "md5sum by W3"}, {"md5": "72bc3cdb", "path": "ask624/w4/b1/sck624.js", "note": "the Library entry SCK624; read whole by W3", "source": "md5sum and read by W3"}, {"md5": "f3384409", "path": "ask624/w4/b1/t624.cjs", "note": "the test", "source": "md5sum by W3"}, {"md5": "57481d2e", "path": "ask624/w4/b1/notes624_5.md", "note": "build notes with the REV 1 section", "source": "md5sum and read by W3"}, {"md5": "70b77c58", "path": "ask624/w4/write/write624.sh", "note": "the write script (engine only)", "source": "md5sum by W3"}, {"md5": "91599f68", "path": "ask624/w4/write/write624_run.txt", "note": "the write log", "source": "md5sum and read by W3"}, {"md5": "dd0d770c", "path": "ask624/w4/write/fetchback_eng_624.json", "note": "engine fetch-back after the write", "source": "md5sum by W3"}]$j$::jsonb,
  $j${"engine": {"path": "ask624/w4/write/revert_eng_624.json", "md5": "6d1f37cb", "note": "the engine before the write (912dd47a)"}, "child": "not written; nothing to revert", "database": "none", "rehearsed": "not stated in the notes or the Wall posts W3 read", "source": "md5sum by W3; notes624_5.md"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 to N4 (the plan, rev 1, sha256 b4164b24); N1 to N4 applied in rev 2", "wall_id": 11841, "md5_graded": "plan rev 1 (sha256 b4164b24; file kept as plan624_5_rev1.md)", "verdict_norm": "PASS", "source": "Wall 11841"}, {"seat": "W1", "verdict": "FAIL on one fix, F1 (the build rev 0, target sha256 3f0c688c: three new catch blocks record nothing; ASK 599 rule 7). Objective met in behaviour.", "wall_id": 11878, "md5_graded": "build rev 0 (target sha256 3f0c688c; replaced by rev 1)", "verdict_norm": "FAIL", "source": "Wall 11878"}, {"seat": "W1", "verdict": "PASS (the build rev 1, target sha256 bafa0a0c = md5 7f129112; rebuild byte-equal; t624 ALL PASS on W1's copy; F1 closed)", "wall_id": 11883, "md5_graded": "7f129112", "verdict_norm": "PASS", "source": "Wall 11883 (names the target bafa0a0c); md5sum and sha256sum of the file by W3"}]$j$::jsonb,
  ARRAY['7f129112'], '[41900]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 (engine)", "before": "912dd47a", "after": "2df7f6fa-d552-4764-aa31-05789a149925 (20:37 CST 2026-11-24), active, 423 nodes; only the Shared Library changed (11 Library lines changed, 1 added, each tagged ASK 624.5; 13 MAP keys change text through lines 1370 and 1375); connections equal"}, {"kind": "n8n workflow", "name": "ODV1 Alternate Pass (child)", "before": "aad0ad9c", "after": "aad0ad9c, unchanged; it takes the engine's library text in the call"}]$j$::jsonb,
  $j$[{"name": "t624.cjs", "result": "ALL PASS on W4's copy and on W1's copy: C1 judgment 1276 sends 3 and records 2; C2 the eleven other judgments send none; C3 the WHICH HOLDS change applies on the target and not on the base, and the second check clears it; C4 a KEEP stays open and an applied change that still disagrees stays open; C5 scope; C6 tags, compile, and every new catch records its fault. Not re-run by W3.", "source": "notes624_5.md; Wall 11878, 11883"}, {"name": "Standing set, pair check, one-copy check", "result": "standing 31 PASS, 0 FAIL before and after the write; pair Library Check PASSES (lib 0f8a6b2950f7de68, map 6e1943a997007de3); one-copy PASS", "source": "write624_run.txt 91599f68; Wall 11893, 11895"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (engine 2df7f6fa, active, 423 nodes; parameters and connections equal the graded target bafa0a0c; only the Shared Library differs from 912dd47a; child aad0ad9c unchanged; standing 31 PASS, 0 FAIL; pair passes)", "wall_id": 11895, "source": "Wall 11895"}]$j$::jsonb,
  $j${"case": "UNEXERCISED: no run since the write (debate_results last row 17:21 CST 2026-11-24, run 42373).", "marks": "a debate_enforcer_log row of rule E-SCK that is sent and answered; AUDIT v60 SELF-CHECK lines; no stored judgment whose engine word names one side beside a WHICH HOLDS line for the other. Two live runs are owed; the item is likely rare.", "source": "plan624_5.md RUN EVIDENCE; Wall 11895; W3's SQL at 20:37 CST 2026-11-24"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "not yet at the draft of this row. W3's entry is manual1123/w3/a6245/em_pairs_6245_draft2.json d03baf9f (parts 09.1, 11.0 and 09.8, one pair each), with W1 for grade (Wall 11899), not carded."}$j$::jsonb,
  'read back', $j$[11841, 11878, 11881, 11883, 11893, 11895, 11898]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "planned, built and wrote ASK 624.5 on the operator's cards", "wall_id": 11893}]$j$::jsonb, current_setting('truth.session_id') FROM s;
